#include <array>
#include <cstddef>
#include <iostream>

int asignarDesde(int& destino, const int& fuente, int cambio) {
    // Conserva el valor previo de fuente y valida antes de modificar destino.
    std::cout << "Funcion pendiente: " << destino << ',' << fuente << ',' << cambio << '\n';
    return -1;
}

int main() {
    std::array<int, 3> datos{2, 5, 8};
    int cantidad = 0;

    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 12) {
        return 1;
    }
    for (int orden = 0; orden < cantidad; ++orden) {
        int destino = 0;
        int origen = 0;
        int cambio = 0;

        if (!(std::cin >> destino >> origen >> cambio)) {
            return 1;
        }
        if (destino < 0 || destino > 2 || origen < 0 || origen > 2) {
            std::cout << "Indices invalidos;OrigenPrevio:-1";
        } else {
            const int previo = asignarDesde(datos[static_cast<std::size_t>(destino)],
                                            datos[static_cast<std::size_t>(origen)], cambio);
            std::cout << (previo < 0 ? "Rechazo" : "Aceptada") << ";OrigenPrevio:" << previo;
        }
        std::cout << ";Datos:" << datos[0] << ',' << datos[1] << ',' << datos[2] << '\n';
    }

    return 0;
}

